insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('8206631d-d11d-5598-b9a1-d45062084e44', 'first-thursdays-cape-town', 'First Thursdays', 'ART_CULTURE', 'PUBLISHED', 'Monthly late-evening event when city-centre galleries and cultural spaces stay open late.', 'On the first Thursday of every month, First Thursdays invites people to explore the cultural life of the city until late. The organisers publish a Cape Town programme listing the participating venues.', 'CITY_CENTRE', 'Participating venues across central Cape Town (see the monthly programme)', 'https://www.first-thursdays.co.za/', 180, 'CHECK_OPERATOR', false, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'CAPE_TOWN', 'City centre', -33.91695, 18.42266, 'EVENT', 'First Thursday of every month, from late afternoon into the evening.', 'Galleries and venues open into the evening; each venue sets its own programme.', 'Check the monthly programme for participating venues and times.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
