insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('39ed96d0-6378-5448-96e8-b721261b563c', 'iziko-slave-lodge', 'Iziko Slave Lodge', 'MUSEUM_HISTORY', 'PUBLISHED', 'One of Cape Town''s oldest buildings, now a museum focused on slavery and human rights.', 'The Slave Lodge is one of the oldest buildings in Cape Town and has served many purposes over three centuries. Iziko''s exhibitions address slavery and human-rights awareness, with temporary exhibitions alongside.', 'CITY_CENTRE', 'Corner of Adderley and Wale Streets, Cape Town', 'https://www.iziko.org.za/museums/slave-lodge/', 75, 'OPENING_HOURS', false, true, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'KNOWN', null, 'CAPE_TOWN', 'City centre', -33.92517, 18.42077, 'ATTRACTION', null, 'Permanent and temporary exhibitions in a 17th-century building.', 'Telephone: +27 21 481 3967. Closed on Christmas Day and Workers'' Day.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
