insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('3031ec29-78aa-5ec0-863f-18b9a3564287', 'heart-of-cape-town-museum', 'Heart of Cape Town Museum', 'MUSEUM_HISTORY', 'PUBLISHED', 'Museum at Groote Schuur Hospital about the world''s first human heart transplant.', 'The Heart of Cape Town Museum is at Groote Schuur Hospital, where the first human heart transplant took place. It is seen on guided tours.', 'SOUTHERN_SUBURBS', 'Groote Schuur Hospital, Main Road, Observatory, Cape Town', 'https://www.heartofcapetown.co.za/', 90, 'SESSIONS', false, true, null, null, 'Booking recommended; group bookings essential.', 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'CAPE_TOWN', 'Observatory', -33.94117, 18.46262, 'ATTRACTION', null, 'A guided tour of the rooms where the 1967 transplant took place.', 'Weekday guided tours at 09:00, 11:00 and 13:00, with a 15:00 tour by prior booking. Weekend tours only for booked groups of at least six. Group bookings are essential. Telephone: +27 21 404 1967.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
