insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('fb14eaea-a2ae-5613-b896-612f8f64e25c', 'lions-head-hike', 'Lion''s Head hike', 'HIKING', 'PUBLISHED', 'Short but popular hike to a peak with 360-degree views over the Atlantic seaboard, city and Table Mountain.', 'Lion''s Head is the peak to the right of Table Mountain when you face it. SANParks describes a short but popular hike with 360-degree views of the Atlantic seaboard, the city and Table Mountain.', 'TABLE_MOUNTAIN', 'Lion''s Head, Table Mountain National Park, Cape Town', 'https://www.sanparks.org/parks/table-mountain/what-to-do/attractions/lions-head-signal-hill', 180, 'ALWAYS_OPEN', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'SANParks does not publish a distance, duration or difficulty grade on the pages checked.', 'CAPE_TOWN', 'Signal Hill', -33.93648, 18.39504, 'ATTRACTION', null, 'A steady climb around the peak to the summit, with views in every direction.', 'SANParks lists Lion''s Head among the park''s five most popular hiking routes. Do not feed or touch animals, and stay on paths.', 'SANParks advises that full-moon hikes should be done only in groups led by someone experienced.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
