insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('3c62bbcb-1f7f-5880-ad66-2d27a83ede68', 'tygerberg-nature-reserve', 'Tygerberg Nature Reserve', 'NATURE', 'PUBLISHED', '388-hectare reserve protecting the largest remnant of Swartland shale renosterveld, with walking trails.', 'The City of Cape Town''s Tygerberg Nature Reserve protects the largest remaining area of critically endangered Swartland shale renosterveld. It has walking trails and picnic spots over 388 hectares.', 'NORTHERN_SUBURBS', 'Totius Street, Welgemoed, Bellville', 'https://www.capetown.gov.za/explore-and-enjoy/see-all-city-facilities/our-recreational-facilities/nature-reserves/tygerberg-nature-reserve/', 120, 'OPENING_HOURS', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'KNOWN', null, 'CAPE_TOWN', 'Welgemoed', -33.85885, 18.58676, 'ATTRACTION', null, 'Walking and hiking trails, views over the northern suburbs, and wildlife and plants of the renosterveld.', 'Closed on Christmas Day and Good Friday.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
