insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('463e6555-a4b4-5f85-9960-cef49a9a09fe', 'helderberg-nature-reserve', 'Helderberg Nature Reserve', 'NATURE', 'PUBLISHED', 'Reserve on the slopes of the Helderberg overlooking False Bay, with walks from 2.2 km to a seven-hour hike.', 'The Helderberg Nature Reserve lies on the slopes of the Helderberg mountain in Somerset West, overlooking False Bay. The Friends of the reserve list walks ranging from 2.2 km to a seven-hour hike, plus picnic spots.', null, 'Helderberg Nature Reserve, Somerset West', 'https://www.helderbergnaturereserve.co.za/', 180, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'CAPE_TOWN', 'Somerset West', -34.04462, 18.87326, 'ATTRACTION', null, 'Marked walks of different lengths and picnic spots. Braai and gas fires are not allowed.', null, null, null, 'PARTLY_CLOSED', 'The reserve''s restaurant is closed until further notice (checked 4 October 2026).', '2026-10-04', '2026-10-04', now(), now(), now());
