insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('b6bef9ad-f7da-5e7a-a835-7ab01a10a1b1', 'kirstenbosch-tree-canopy-walkway', 'Kirstenbosch Tree Canopy Walkway (the Boomslang)', 'NATURE', 'PUBLISHED', '130 m curved walkway through the Kirstenbosch arboretum, rising to 12 m above the ground.', 'The Centenary Tree Canopy Walkway, informally called the Boomslang, is a curved steel and timber walkway through the trees of the Kirstenbosch Arboretum. It is 130 m long, rises 12 m above the ground and opened on 17 May 2014.', 'SOUTHERN_SUBURBS', 'Kirstenbosch National Botanical Garden, Newlands', 'https://www.sanbi.org/gardens/kirstenboch/tours/tree-canopy-walkway/', 45, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'KNOWN', null, 'CAPE_TOWN', 'Newlands', -33.98561, 18.43014, 'ATTRACTION', null, 'A walk from the forest floor up through and above the canopy, with views of the mountains, the garden and the Cape Flats.', 'SANBI charges no extra fee beyond normal garden entry.', null, 'Wheelchair accessible with assistance. The arboretum is on a slope, so wheelchair users need help on the steep gradients. SANBI recommends entering at Rycroft Gate (Gate 3) and using the walkway''s eastern entry point.', 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
