insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('cc5817b8-7a9f-5a12-a86c-e25c65d340f1', 'tandem-paragliding-cape-town', 'Tandem paragliding from Signal Hill or Lion''s Head', 'ADVENTURE', 'PUBLISHED', 'Tandem flights with SAHPA-licensed instructors, landing on the Sea Point promenade.', 'Fly Cape Town runs tandem paragliding flights with instructors licensed by SAHPA. Flights launch from Signal Hill or Lion''s Head and land at the Sea Point promenade. No experience is needed.', 'TABLE_MOUNTAIN', 'Launch from Signal Hill or Lion''s Head; landing at Sea Point promenade', 'https://www.flycapetown.co.za/', 90, 'SCHEDULE_VARIES', true, false, 14, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'PARTLY_KNOWN', 'Fly Cape Town states an age limit of 14 and over and a weight range of 20 kg to 120 kg. Elsewhere on its site it mentions flying with children as young as ten, so confirm age rules with the operator.', 'CAPE_TOWN', 'Signal Hill', -33.917, 18.40391, 'ATTRACTION', null, 'A short briefing, a running launch with your instructor and a flight over the Atlantic seaboard.', 'Flights last between 6 and 15 minutes, depending on wind and weather.', 'Flights depend on the wind and weather on the day.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
