insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('10139a16-14ad-5b2a-b492-7c9d5867d44b', 'hout-bay-seal-island-cruise', 'Boat trip to Seal Island from Hout Bay', 'WILDLIFE', 'PUBLISHED', 'Daily boat trips of about 45 minutes from Hout Bay harbour to the seal colony and past the Sentinel.', 'Circe Launches, Hout Bay''s original Seal Island boat operator, runs daily trips to the island''s seal colony and past the Sentinel mountain. Trips take about 45 minutes.', 'HOUT_BAY_CHAPMANS', 'Hout Bay (departure point confirmed on booking)', 'https://www.circelaunches.co.za/', 45, 'SESSIONS', true, false, null, null, 'Bookings are essential.', 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'KNOWN', null, 'CAPE_TOWN', 'Hout Bay', -34.04791, 18.34763, 'ATTRACTION', null, 'A boat trip to see the seals on the island, with views of the Sentinel.', 'Daily departures at 09:00, 09:45, 10:30 and 15:00, plus a 12:00 departure on weekends and public holidays. Bookings are essential.', 'All departures are weather permitting.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
