insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('d63e81d0-f40c-50c4-9162-a1f5df13a605', 'jonkershoek-nature-reserve', 'Jonkershoek Nature Reserve', 'HIKING', 'PUBLISHED', 'Mountain reserve about 9 km from Stellenbosch with hikes of 5.3 km to 18 km, rock pools and mountain biking.', 'CapeNature''s Jonkershoek Nature Reserve covers the Jonkershoek Mountains about 9 km from Stellenbosch. Four more challenging hikes range from 5.3 km to 18 km, and the reserve has mountain biking, rock pools and waterfalls.', null, 'Jonkershoek Valley Road, Stellenbosch', 'https://www.capenature.co.za/reserves/jonkershoek-nature-reserve', 240, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'CAPE_WINELANDS', 'Stellenbosch', -33.93556, 18.88708, 'ATTRACTION', null, 'Mountain trails, rock pools and waterfalls. The Swartboskloof to Sosyskloof trail is 5.3 km (6.9 km with the lookout) and takes about 2 to 2.5 hours.', 'Hiking permits are sold by CapeNature.', null, null, 'PARTLY_CLOSED', 'From 23 March 2026 until further notice, parking on the circular route is closed. Visitors must use the outside parking and walk about 5 km further.', '2026-10-04', '2026-10-04', now(), now(), now());
