insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('53c390f6-4103-5e57-9511-49496086c838', 'bainskloof-pass', 'Limietberg Nature Reserve (Bainskloof)', 'HIKING', 'PUBLISHED', 'Mountain reserve in the Du Toitskloof range with river valleys, campsites and trails.', 'CapeNature''s Limietberg Nature Reserve lies in the Du Toitskloof Mountains near Paarl, with cliffs and indigenous river valleys. It has walks and hikes, freshwater angling with a permit, and campsites.', null, 'Limietberg Nature Reserve, Bainskloof, Wellington', 'https://www.capenature.co.za/reserves/limietberg-nature-reserve', 240, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'CAPE_WINELANDS', 'Wellington', -33.733, 19.12113, 'ATTRACTION', null, 'Mountain trails, river pools and historic sites.', 'The reserve''s hiking trails are only for campers, not picnickers. The Tweede Tol campsite entrance has a 3.2 m height restriction. Alcohol is not permitted. Permits are sold at the reserve.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
