insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('e3c94c7b-4948-58d8-b553-c9ca0b46c245', 'hermanus-cliff-path', 'Hermanus Cliff Path and land-based whale watching', 'HIKING', 'PUBLISHED', '12 km coastal path through Hermanus with whale-watching viewpoints over Walker Bay.', 'South African Tourism, citing the official Hermanus website, describes the Cliff Path as 12 km of whale-watching viewpoints from one end of Hermanus to the other. Other viewing spots include Gearing''s Point, the Old Harbour terraces and Siever''s Point.', null, 'Cliff Path, Hermanus', 'https://www.southafrica.net/gl/en/travel/article/the-9-best-spots-in-hermanus-to-watch-whales', 120, 'ALWAYS_OPEN', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Hermanus', -34.41123, 19.26132, 'ATTRACTION', null, 'A walk of any length along the cliffs, stopping at viewpoints. The Old Harbour has viewing terraces and information boards about the whales.', null, 'The most common whale seen in Hermanus is the southern right whale. Boat operators in Hermanus describe June to the end of November as peak season.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
