insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('d5ec68f0-a2f1-57bc-a341-a63191456cc3', 'hermanus-boat-whale-watching', 'Boat-based whale watching from Hermanus', 'WILDLIFE', 'PUBLISHED', 'Whale-watching boat trips from Hermanus New Harbour, with peak season June to November.', 'Southern Right Charters runs whale-watching boat trips from the New Harbour in Hermanus. It describes June to the end of November as peak season for southern right and humpback whales.', null, 'The Whale Shack, New Harbour, Hermanus', 'https://www.southernrightcharters.co.za/', 120, 'SCHEDULE_VARIES', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Hermanus', -34.43231, 19.22587, 'ATTRACTION', null, 'A boat trip on Walker Bay to look for whales and dolphins.', 'Trip status is updated daily at about 16:00. Telephone: +27 82 353 0550.', 'All trips are weather and sea permitting. Booking is advised.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
