insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('258761bc-d2ba-54fa-aa0e-0c3ba56a6569', 'gansbaai-marine-tours', 'Marine Big 5 boat tours from Gansbaai', 'WILDLIFE', 'PUBLISHED', 'Boat tours around Dyer Island to look for whales, dolphins, seals, sharks and African penguins.', 'Marine Dynamics runs whale-watching and Marine Big 5 tours from Gansbaai around the Dyer Island ecosystem. Southern right whales visit between June and December, and Geyser Rock is home to thousands of Cape fur seals.', null, 'Gansbaai (departure point confirmed on booking)', 'https://www.whalewatchsa.com/', 180, 'SCHEDULE_VARIES', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Gansbaai', -34.58278, 19.35222, 'ATTRACTION', null, 'A boat tour to Dyer Island and Geyser Rock with a guide and crew.', null, 'Southern right whales: June to December. Humpback and Bryde''s whales may be seen from January to May.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
