insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('b1c0b354-8219-561b-97e7-689d4b180b0c', 'stony-point-penguins', 'Stony Point penguin colony', 'WILDLIFE', 'PUBLISHED', 'CapeNature reserve in Betty''s Bay with an African penguin colony seen from a boardwalk.', 'Stony Point Nature Reserve in Betty''s Bay is home to a colony of African penguins, which visitors watch from a boardwalk. CapeNature puts the drive from Cape Town at 70 to 90 minutes.', null, 'Stony Point Nature Reserve, Betty''s Bay', 'https://www.capenature.co.za/reserves/stony-point-nature-reserve', 60, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Betty''s Bay', -34.37183, 18.89407, 'ATTRACTION', null, 'A boardwalk along the colony with views of the penguins and seabirds.', 'The boardwalk closes at 16:00 and the reserve at 16:30; the last permit is issued at 15:45. Opening time was not captured. Reserve office: 087 087 3001.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
