insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('e99d2949-3f74-5195-a3ea-b094a4c966fd', 'harold-porter-botanical-garden', 'Harold Porter National Botanical Garden', 'NATURE', 'PUBLISHED', 'SANBI garden in Betty''s Bay set in coastal fynbos, with kloof trails to waterfalls.', 'Harold Porter National Botanical Garden lies in the heart of the coastal fynbos. It covers mountain slopes, kloofs and wetlands, and SANBI lists trails including Leopard''s Kloof, Disa Kloof and the Fynbos and Zigzag trails.', null, 'Harold Porter National Botanical Garden, Betty''s Bay', 'https://www.sanbi.org/gardens/harold-porter/', 150, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Betty''s Bay', -34.3465, 18.93168, 'ATTRACTION', null, 'Cultivated garden sections, fynbos trails, waterfalls and amber pools, and a restaurant.', null, null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
