insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('27425037-6dc2-5de9-a288-2c6a2e25e658', 'kogelberg-nature-reserve', 'Kogelberg Nature Reserve', 'HIKING', 'PUBLISHED', 'CapeNature reserve between Gordon''s Bay and Kleinmond, known for mountain fynbos and day hikes.', 'Kogelberg Nature Reserve lies between Gordon''s Bay and Kleinmond and protects some of the finest mountain fynbos in the Western Cape. Visitor numbers are limited, and day-hike permits are needed.', null, 'Kogelberg Nature Reserve, between Gordon''s Bay and Kleinmond', 'https://www.capenature.co.za/reserves/kogelberg-nature-reserve', 240, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Kleinmond', -34.26184, 18.9295, 'ATTRACTION', null, 'Day walks through fynbos and river valleys. The Highlands Trail is a two-day hike.', 'Parking at trailheads is first come, first served. Permits are sold at the reserve office or through CapeNature Central Reservations. Closed shoes are essential, and a baboon troop lives in the reserve.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
