insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('66bbb1c4-0f70-5503-a69d-f619cd4b477f', 'cape-canopy-tour', 'Cape Canopy Tour', 'ADVENTURE', 'PUBLISHED', 'Guided zipline tour of 13 platforms in the Hottentots Holland mountains, for ages five and up.', 'Cape Canopy Tour is a guided zipline route in the Hottentots Holland mountains near Elgin. It has 13 platforms and a suspension bridge over a double waterfall.', null, 'Off the R321 above Elgin (directions from the N2 Elgin/Grabouw turn-off)', 'https://capecanopytour.co.za/', 270, 'SCHEDULE_VARIES', true, false, 5, null, 'Advance booking and pre-payment required.', 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'KNOWN', 'From age 5, with no upper age limit, but you must manage the 1 km walk out. Children aged 5 to 9 usually ride tandem with a guide.', 'OVERBERG', 'Elgin', -34.02725, 19.03541, 'ATTRACTION', null, 'About 4.5 hours with guides, including a 1 km walk out of the mountain.', 'Book online in advance and pre-pay. Daily transfers from Cape Town can be added for at least two guests.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
