insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('140a3859-01b3-5722-a96d-f4006af7d92c', 'de-hoop-nature-reserve', 'De Hoop Nature Reserve', 'WILDLIFE', 'PUBLISHED', 'Large CapeNature reserve about three hours from Cape Town, popular with hikers, cyclists and whale watchers.', 'De Hoop is one of CapeNature''s largest reserves, at 34,000 hectares, with a marine reserve extending 5 km out to sea. It is home to the Western Cape''s last remaining breeding colony of the rare Cape vulture.', null, 'De Hoop Nature Reserve, Overberg', 'https://www.capenature.co.za/reserves/de-hoop-nature-reserve', 360, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Bredasdorp district', -34.44636, 20.60222, 'ATTRACTION', null, 'Day hikes such as the Klipspringer and coastal trails, cycling, birding and whale watching. The multi-day Whale Trail is booked separately.', 'Whale Trail bookings: CapeNature call centre, 087 087 8250.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
