insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('ac511166-8eea-5830-b66c-499340edaa74', 'cape-agulhas', 'Cape Agulhas: the southernmost tip of Africa', 'NATURE', 'PUBLISHED', 'Cairn marking Africa''s southernmost point, where the Atlantic and Indian oceans officially meet.', 'In Agulhas National Park, a cairn marks the southernmost tip of Africa at 34°49''58"S, 20°00''12"E, where the Atlantic and Indian oceans officially meet. Nearby, the Cape Agulhas Lighthouse is the second-oldest working lighthouse in southern Africa and houses a museum.', null, 'Agulhas National Park, L''Agulhas', 'https://www.sanparks.org/parks/agulhas/what-to-do/activities/scenic-landmarks', 120, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'L''Agulhas', -34.83314, 19.99994, 'ATTRACTION', null, 'The cairn at the tip, the lighthouse (71 steps to the top) and its museum, Khoisan stone fish traps and the Meisho Maru 38 wreck.', null, null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
