insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('e2022b1f-e699-577d-9375-6c17cb052a69', 'drostdy-museum-swellendam', 'Drostdy Museum', 'MUSEUM_HISTORY', 'PUBLISHED', 'Museum complex around the 1747 Drostdy, the Dutch East India Company''s seat in Swellendam.', 'The Drostdy in Swellendam was built by the Dutch East India Company in 1747 as the landdrost''s residence and headquarters. The museum complex includes the Old Gaol, Mayville House Museum, craft workshops and gardens.', null, 'Drostdy Museum, Swellendam', 'https://www.drostdymuseum.com/', 90, 'CHECK_OPERATOR', false, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Swellendam', -34.01942, 20.45267, 'ATTRACTION', null, 'Period rooms, the old gaol, a smithy and wagonmaker''s shop, a mill and gardens.', 'Hours were not captured from the page checked.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
