insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('e599fea6-4b6d-52dc-b2fd-fc4bc8285a9e', 'bontebok-national-park', 'Bontebok National Park', 'WILDLIFE', 'PUBLISHED', 'Park on the outskirts of Swellendam protecting the bontebok, with game drives, river swimming and walks.', 'Bontebok National Park lies on the outskirts of Swellendam, below the Langeberg mountains, within the Cape Floristic Region. Visitors drive around the park to spot bontebok, grey rhebok and red hartebeest.', null, 'Bontebok National Park, Swellendam', 'https://www.sanparks.org/parks/bontebok/', 180, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Swellendam', -34.06766, 20.46557, 'ATTRACTION', null, 'Self-drive game viewing, birding, cycling, river swimming and walking trails.', 'Keep to the speed limit to protect wildlife.', null, null, 'UNKNOWN', 'SANParks posted a short-term closure notice for the park on 4 June 2026; check current access before visiting.', '2026-10-04', '2026-10-04', now(), now(), now());
