insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('274c18e2-b6a0-5752-9e9f-bcc13d16e201', 'stanford-river-cruise', 'Lady Stanford river cruise', 'WILDLIFE', 'PUBLISHED', 'Guided cruise on the Klein River from Stanford towards the Hermanus estuary, known for birdlife.', 'Grootbos runs the Lady Stanford, a guided cruise from Stanford village down the Klein River towards the Hermanus estuary and back. The boat seats up to 26, and guides point out birds such as blue cranes, flamingos and African fish eagles.', null, 'Stanford village (departure point confirmed on booking)', 'https://www.grootbos.com/en/experiences/lady-stanford-river-cruises', 120, 'SCHEDULE_VARIES', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'OVERBERG', 'Stanford', -34.43936, 19.45448, 'ATTRACTION', null, 'A quiet cruise with binoculars, bird books, blankets and an on-board eco toilet; sundowner cruises are also offered.', null, 'Cruises are weather dependent.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
