insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('baa8ecf5-5dae-5658-8202-29c3e9320fa0', 'hottentots-holland-nature-reserve', 'Hottentots Holland Nature Reserve', 'HIKING', 'PUBLISHED', '70,000-hectare mountain reserve about 90 km from Cape Town, with day and overnight hikes.', 'Hottentots Holland Nature Reserve covers 70,000 hectares of the Hottentots Holland Mountains, from Elgin to beyond Villiersdorp, and is part of a World Heritage Site. Hikes range from day outings to overnight routes, and 110 bird species have been recorded.', null, 'Hottentots Holland Nature Reserve, near Grabouw', 'https://www.capenature.co.za/reserves/hottentots-holland-nature-reserve', 300, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'PARTLY_KNOWN', 'Children under 12 may not hike the overnight trails.', 'OVERBERG', 'Grabouw', -34.02725, 19.03541, 'ATTRACTION', null, 'Day hikes and overnight trails through mountain fynbos, with huts at Landroskop and Boesmanskloof.', 'Permits are sold at the reserve office or through CapeNature. No picking flowers or collecting seeds; fires only in designated areas.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
