insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('777e3ce5-5051-5d7b-96b1-8b1465cf1da3', 'postberg-flowers', 'Postberg wildflower season', 'NATURE', 'PUBLISHED', 'Annual flower season in West Coast National Park; the Postberg section opens only during flower season.', 'West Coast National Park has a colourful flower season each year between August and September. Flowers are most prominent in the Postberg section, which is open to the public only during the flower season. Displays depend on winter rainfall.', null, 'Postberg section, West Coast National Park, Langebaan', 'https://www.sanparks.org/parks/west-coast/what-to-do/activities/flower-season', 300, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'WEST_COAST', 'Langebaan', -33.10972, 18.00833, 'EVENT', 'Annually in August and September, depending on rainfall.', 'A drive or hike through Postberg, with game among the flowers.', null, 'August to September only. SANParks announced that the 2026 season was underway on 7 August 2026.', null, 'SEASONAL', 'Postberg opens to the public only during the flower season.', '2026-10-04', '2026-10-04', now(), now(), now());
