insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('e212f1d5-45b2-5cea-9977-4e25385a92c9', 'west-coast-fossil-park', 'West Coast Fossil Park', 'MUSEUM_HISTORY', 'PUBLISHED', 'World-renowned fossil site with guided tours, about 150 km north of Cape Town.', 'The Langebaanweg fossil site, in the West Coast Fossil Park, is known worldwide for its well-preserved fossil fauna. It is about 150 km, or roughly a 1.5-hour drive, north of Cape Town.', null, 'R45, Langebaanweg, Vredenburg', 'https://www.fossilpark.org.za/', 120, 'OPENING_HOURS', false, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'KNOWN', null, 'WEST_COAST', 'Langebaanweg', -32.9649, 18.10783, 'ATTRACTION', null, 'Exhibitions and guided tours of the fossil site.', 'Weekday tours at 10:00, 11:00, 12:00, 13:00, 14:00 and 15:00; weekend tours at 10:00, 11:00, 12:00 and 13:00. Closed on Mondays, Christmas Day, New Year''s Day and Good Friday.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
