insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('c3e8828a-d7f8-5ee8-9aaa-4a9c29e9d746', 'langebaan-kitesurfing', 'Kitesurfing and water sports on Langebaan Lagoon', 'ADVENTURE', 'PUBLISHED', 'Water-sports centre on Langebaan Lagoon offering kitesurfing, windsurfing, wing foiling, SUP and kayaking.', 'Cape Sports Center in Langebaan offers courses and equipment for kitesurfing, windsurfing, wing foiling, surfing, stand-up paddling and kayaking on the lagoon, plus an on-site rooftop bar.', null, 'Cape Sports Center, Langebaan', 'https://www.capesport.co.za/', 180, 'SCHEDULE_VARIES', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age and swimming requirements were not shown on the page checked.', 'WEST_COAST', 'Langebaan', -33.09072, 18.03489, 'ATTRACTION', null, 'Lessons or equipment hire on the lagoon.', 'Telephone: 022 100 0982.', 'Kitesurfing and windsurfing depend on the wind.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
