insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('5e263075-0546-5c14-8505-7b9a38ac21c0', 'rocherpan-nature-reserve', 'Rocherpan Nature Reserve', 'WILDLIFE', 'PUBLISHED', '930-hectare seaside reserve with a seasonal vlei, known for birds and wildflowers.', 'CapeNature''s Rocherpan Nature Reserve lies 25 km north of Velddrif. It consists mainly of a seasonal vlei that is usually dry in summer. It became a reserve in 1966, and the adjacent ocean is a marine protected area.', null, 'Rocherpan Nature Reserve, 25 km north of Velddrif', 'https://www.capenature.co.za/reserves/rocherpan-nature-reserve', 180, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'WEST_COAST', 'Velddrif', -32.58528, 18.30954, 'ATTRACTION', null, 'Birdwatching, two short trails (one along the beach, one along the vlei), picnics and mountain biking.', 'Both trails are relatively easy, taking no longer than four hours each. Angling permits are bought at a post office, not at the reserve.', 'The vlei is usually dry in summer.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
insert into activity_sources (id, activity_id, url, publisher, source_type, covers, accessed_on, sort_order) values ('50ec3278-f801-50ef-8a90-7dd11047247e', '5e263075-0546-5c14-8505-7b9a38ac21c0', 'https://www.capenature.co.za/reserves/rocherpan-nature-reserve', 'CapeNature', 'PUBLIC_AUTHORITY', 'Reserve, trails and permits', '2026-10-04', 0);
