insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('e28ac07d-bd31-56c7-8440-7b36b4d1917e', 'cederberg-wilderness', 'Cederberg Wilderness Area', 'HIKING', 'PUBLISHED', '71,000 hectares of rugged mountains with sandstone formations and San and Khoi rock art, 250 km from Cape Town.', 'The Cederberg Wilderness Area covers about 71,000 hectares of mountains, from the Middelberg Pass at Citrusdal to north of the Pakhuis Pass at Clanwilliam, about 250 km north of Cape Town. It is known for hiking, rock climbing, sandstone formations and ancient rock art.', null, 'Cederberg Wilderness Area (Algeria office), Clanwilliam district', 'https://www.capenature.co.za/reserves/cederberg-wilderness-area', 480, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'KNOWN', 'Minimum of three adult hikers per group; maximum 12.', 'WEST_COAST', 'Clanwilliam', -32.36504, 19.11282, 'ATTRACTION', null, 'Day and multi-day hikes in tough wilderness terrain with few facilities.', 'At least three adults are required for any wilderness trail; ideal groups are 4 to 12. Each zone allows 50 people a day. Fires, including gas cookers, are forbidden, and all waste must be carried out.', null, null, 'PARTLY_CLOSED', 'Algeria Campsite is closed for two years after flood damage, and CapeNature has issued post-fire and flood updates. Check closures before visiting.', '2026-10-04', '2026-10-04', now(), now(), now());
insert into activity_sources (id, activity_id, url, publisher, source_type, covers, accessed_on, sort_order) values ('49fe1245-fa27-5f2d-a44b-6a3b20a1fd82', 'e28ac07d-bd31-56c7-8440-7b36b4d1917e', 'https://www.capenature.co.za/reserves/cederberg-wilderness-area', 'CapeNature', 'PUBLIC_AUTHORITY', 'Reserve, closures and hiking rules', '2026-10-04', 0);
