insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('b0272ee5-11f4-5cdd-be8c-5d095b80ed7d', 'wolfberg-cracks-and-arch', 'Wolfberg Cracks and Arch hike', 'HIKING', 'PUBLISHED', 'Cederberg day hike to the Wolfberg Arch; day permits from Sanddrif, Driehoek or Keurbosfontein.', 'The Wolfberg Arch is one of the Cederberg''s best-known sandstone formations. CapeNature sells day-hiking permits for the arch at Sanddrif, Driehoek and Keurbosfontein.', null, 'Sanddrif, Cederberg (permit point)', 'https://www.capenature.co.za/activities/hiking-and-walking-cederberg-wilderness-area-1', 480, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'PARTLY_KNOWN', 'Minimum of three adults per group. CapeNature does not publish a distance or duration for this route on the page checked.', 'WEST_COAST', 'Cederberg', -32.44346, 19.25388, 'ATTRACTION', null, 'A demanding mountain hike to rock formations, in wilderness terrain.', 'Do not hike with fewer than three adults. Carry enough food and water, a map and a medical kit. Trails may close in bad weather.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
