insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('a7aea327-bb1f-53ff-9918-d22d85e14492', 'sevilla-rock-art-trail', 'Sevilla Rock Art Trail', 'HIKING', 'PUBLISHED', '5 km trail along the Brandewyn River past nine rock-art sites, at Traveller''s Rest farm.', 'The Sevilla Rock Art Trail at Traveller''s Rest farm is a 5 km walk along the Brandewyn River that visits nine sites of rock paintings. The farm is 34 km from Clanwilliam on the Wupperthal road (R364), over the Pakhuis Pass.', null, 'Traveller''s Rest farm, R364, 34 km from Clanwilliam', 'https://www.travellersrest.co.za/', 180, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'WEST_COAST', 'Clanwilliam', -32.08476, 19.09009, 'ATTRACTION', null, 'An easy walk with stops at painted rock shelters.', 'Buy permits at the farm stall. No pets, because the trail is in a conservation area.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
