insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('18ea1fa0-a9a8-5614-ba50-3b821d09e49c', 'swartberg-pass', 'Swartberg Pass', 'SCENIC_DRIVE', 'PUBLISHED', '27 km untarred mountain pass between the Klein Karoo and Prince Albert, supported by dry-stone walls.', 'The Prince Albert Tourism Association describes the 27 km Swartberg Pass as one of the finest passes in the world: an untarred road that winds to the summit, held up in places by hand-packed dry-stone retaining walls. CapeNature''s Swartberg Nature Reserve, a World Heritage Site, borders the route.', null, 'Swartberg Pass, between Oudtshoorn and Prince Albert', 'https://www.princealbert.org.za/', 120, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'GARDEN_ROUTE_KLEIN_KAROO', 'Oudtshoorn to Prince Albert', -33.35225, 22.04614, 'ATTRACTION', null, 'A slow gravel-road drive with viewpoints and striking geology.', 'CapeNature lists Prince Albert as 5 km from the pass and Oudtshoorn as 40 km.', 'Check road conditions before driving the pass.', null, 'OPEN', 'The side road to Gamkaskloof (Die Hel) is closed until further notice, according to CapeNature.', '2026-10-04', '2026-10-04', now(), now(), now());
