insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('4d597deb-8acd-5a26-91b3-45e4d8922c30', 'robberg-nature-reserve', 'Robberg Nature Reserve', 'HIKING', 'PUBLISHED', 'World Heritage peninsula 8 km south of Plettenberg Bay, with trails from 30 minutes to four hours.', 'Robberg Nature Reserve, 8 km south of Plettenberg Bay, is a World Heritage Site. Its rocks date back to the break-up of Gondwanaland, and some caves show evidence of Middle and Later Stone Age people.', null, 'Robberg Nature Reserve, Plettenberg Bay', 'https://www.capenature.co.za/reserves/robberg-nature-reserve', 240, 'CHECK_OPERATOR', true, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'GARDEN_ROUTE_KLEIN_KAROO', 'Plettenberg Bay', -34.10455, 23.41922, 'ATTRACTION', null, 'Three trails, from a 30-minute stroll to a four-hour hike, with sea views and birdlife.', 'Take water and warm clothing, as the weather can change suddenly.', null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
