insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('dfb285b4-06c2-5014-9f64-47ad76abe02b', 'matjiesfontein', 'Matjiesfontein historic village', 'MUSEUM_HISTORY', 'PUBLISHED', 'Preserved Victorian railway village in the Karoo with museums and a London double-decker bus tour.', 'Matjiesfontein is a historic Karoo village built around its railway station. Attractions include two museums, the old post office, a historic cricket pitch, the court house and jail, and a town tour on a red London double-decker bus.', null, 'Matjiesfontein, Central Karoo', 'https://matjiesfontein.com/', 150, 'CHECK_OPERATOR', false, false, null, null, null, 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'CAPE_KAROO', 'Matjiesfontein', -33.23145, 20.58114, 'ATTRACTION', null, 'A short bus tour, museums and historic buildings around the station.', null, null, null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
