insert into activities (id, slug, title, category, status, summary, description, area, address, official_url, typical_duration_minutes, schedule_type, weather_dependent, indoor, min_age, accompaniment_rule, booking_notes, price_status, verification_notes, last_verified_on, verified_by, participation_rules, participation_note, region, town, latitude, longitude, kind, event_schedule, what_to_expect, practical_info, seasonal_info, accessibility_info, operating_status, operating_note, operating_checked_on, existence_verified_on, published_at, created_at, updated_at) values ('9c4dee18-97b0-5f63-acca-949f3db33fe1', 'prince-albert-stargazing', 'Night Sky Tours, Prince Albert', 'FAMILY_LEISURE', 'PUBLISHED', 'Guided stargazing at Wolvekraal Guest Farm with a laser-guided sky tour and telescopes.', 'Night Sky Tours (also called Karoo Astro Tours) runs guided astronomy evenings at Wolvekraal Guest Farm, just outside Prince Albert. Tours include a laser-guided tour of the southern sky and viewing through a 12-inch telescope and a smart telescope.', null, 'Wolvekraal Guest Farm, near Prince Albert', 'https://princealbert.org.za/directory/general/night-sky-tours/', 120, 'SCHEDULE_VARIES', true, false, null, null, 'Book with the operator.', 'NOT_RECORDED', 'Researched against the official sources listed on 2026-10-04. Source record: docs/things-to-do/sources.md.', '2026-10-04', 'SL Tours catalogue research', 'UNKNOWN', 'Age, fitness and other limits were not published on the pages checked. Confirm with the operator before you go.', 'CAPE_KAROO', 'Prince Albert', -33.22263, 22.03033, 'ATTRACTION', null, 'Constellations, planets and deep-sky objects, with star stories from Greek, Roman and Southern African traditions.', 'No astronomy knowledge needed. Contact: info@nightskytours.co.za, +27 82 862 6135.', 'Stargazing depends on clear skies; the sky changes with the seasons.', null, 'OPEN', null, '2026-10-04', '2026-10-04', now(), now(), now());
