insert into vehicle_options (id, slug, name, type_label, fleet_category, passenger_capacity, capacity_status, capacity_note, description, image_url, image_thumbnail_url, image_alt, image_kind, image_credit, image_source_page, image_licence, image_licence_url, spec_source_url, spec_source_publisher, checked_on, sort_order, published) values ('f10eb8eb-a171-5049-b17f-7d4f183a5e36', 'toyota-rumion', 'Toyota Rumion', 'Seven-seat MPV', 'SUV', 5, 'CONFIRMED', 'The Toyota Rumion has seven seats in three rows. Five passengers plus the driver keeps a row free for luggage.', 'A seven-seat people carrier for small families or groups of up to five passengers.', '/assets/vehicles/toyota-rumion.jpg', '/assets/vehicles/toyota-rumion-480.jpg', 'White Suzuki Ertiga MPV', 'ILLUSTRATIVE', 'Alex Neman', 'https://commons.wikimedia.org/wiki/File:2022_Suzuki_Ertiga_GL.jpg', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://www.toyota.co.za/vehicles/toyota-rumion', 'Toyota South Africa', '2026-10-04', 1, true);
insert into vehicle_options (id, slug, name, type_label, fleet_category, passenger_capacity, capacity_status, capacity_note, description, image_url, image_thumbnail_url, image_alt, image_kind, image_credit, image_source_page, image_licence, image_licence_url, spec_source_url, spec_source_publisher, checked_on, sort_order, published) values ('5b3abb3a-c993-5bff-83e3-210dff4a4079', 'hyundai-staria', 'Hyundai Staria', 'People carrier', 'VAN', 8, 'CONFIRMED', 'Hyundai South Africa sells the Staria as a 9-seater and an 11-seater. Eight passengers fit the 9-seater with the driver.', 'A spacious people carrier for groups of up to eight passengers.', '/assets/vehicles/hyundai-staria.jpg', '/assets/vehicles/hyundai-staria-480.jpg', 'White Hyundai Staria people carrier', 'ILLUSTRATIVE', 'Alexander Migl', 'https://commons.wikimedia.org/wiki/File:Hyundai_Staria_1X7A0321.jpg', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://www.hyundai.co.za/new-vehicles/showroom/staria', 'Hyundai Automotive South Africa', '2026-10-04', 2, true);
insert into vehicle_options (id, slug, name, type_label, fleet_category, passenger_capacity, capacity_status, capacity_note, description, image_url, image_thumbnail_url, image_alt, image_kind, image_credit, image_source_page, image_licence, image_licence_url, spec_source_url, spec_source_publisher, checked_on, sort_order, published) values ('312e075f-5247-5487-8b42-4ad27ad01e30', 'mercedes-benz-v-class', 'Mercedes-Benz V-Class', 'Luxury van', 'LUXURY_VAN', 8, 'TO_BE_CONFIRMED', 'Capacity to be confirmed: the V-Class is offered in 6-, 7- and 8-seat layouts including the driver, so eight passengers depends on the vehicle''s configuration.', 'A premium van for small groups who want extra comfort. Seating depends on the vehicle''s configuration.', '/assets/vehicles/mercedes-benz-v-class.jpg', '/assets/vehicles/mercedes-benz-v-class-480.jpg', 'Grey Mercedes-Benz V-Class van', 'ILLUSTRATIVE', 'EurovisionNim', 'https://commons.wikimedia.org/wiki/File:2017_Mercedes-Benz_V_250_d_(W_447)_van_(2017-08-26)_01.jpg', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://www.mercedes-benz.co.za/passengercars/models/van/v-class/overview.html', 'Mercedes-Benz South Africa', '2026-10-04', 3, true);
insert into vehicle_options (id, slug, name, type_label, fleet_category, passenger_capacity, capacity_status, capacity_note, description, image_url, image_thumbnail_url, image_alt, image_kind, image_credit, image_source_page, image_licence, image_licence_url, spec_source_url, spec_source_publisher, checked_on, sort_order, published) values ('b12e3b5b-0a87-5ebb-b6d1-24ed1fb95bb5', 'toyota-quantum', 'Toyota Quantum', 'Minibus', 'MINIBUS', 13, 'CONFIRMED', 'Toyota South Africa lists the 14-seat minibus in this family (Hiace 14-seater) with 14 seats. Thirteen passengers plus the driver fits that seating.', 'A 14-seat minibus for groups of up to thirteen passengers.', '/assets/vehicles/toyota-quantum.jpg', '/assets/vehicles/toyota-quantum-480.jpg', 'White high-roof Toyota HiAce minibus', 'ILLUSTRATIVE', 'Rutger van der Maar', 'https://commons.wikimedia.org/wiki/File:Toyota_Hiace_front.jpg', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://www.toyota.co.za/vehicles/hiace', 'Toyota South Africa', '2026-10-04', 4, true);
insert into vehicle_options (id, slug, name, type_label, fleet_category, passenger_capacity, capacity_status, capacity_note, description, image_url, image_thumbnail_url, image_alt, image_kind, image_credit, image_source_page, image_licence, image_licence_url, spec_source_url, spec_source_publisher, checked_on, sort_order, published) values ('c03f242c-b5ac-504c-9d68-5fea9f00aee5', 'minibus-22-seater', 'Minibus or midibus', '22-seater', 'MINIBUS', 22, 'TO_BE_CONFIRMED', 'Capacity to be confirmed: no specific 22-passenger model has been matched yet, and the vehicle supplied will be confirmed with your quote.', 'A minibus or midibus for groups of about twenty passengers.', '/assets/vehicles/minibus-22-seater.jpg', '/assets/vehicles/minibus-22-seater-480.jpg', 'White Toyota Coaster minibus', 'ILLUSTRATIVE', 'Novoklimov', 'https://commons.wikimedia.org/wiki/File:Toyota_Coaster_in_Egypt_02.jpg', 'CC0', 'http://creativecommons.org/publicdomain/zero/1.0/deed.en', 'https://www.capetowncoachservices.co.za/fleet/22-seater', 'Cape Town Coach Services (market example, not an SL Tours supplier)', '2026-10-04', 5, true);
insert into vehicle_options (id, slug, name, type_label, fleet_category, passenger_capacity, capacity_status, capacity_note, description, image_url, image_thumbnail_url, image_alt, image_kind, image_credit, image_source_page, image_licence, image_licence_url, spec_source_url, spec_source_publisher, checked_on, sort_order, published) values ('ff7620c3-f745-56b7-bdfe-abadd4c65c5a', 'coach-42-seater', 'Coach', '42-seater', 'COACH', 42, 'TO_BE_CONFIRMED', 'Capacity to be confirmed: no 42-passenger coach model has been verified. Operators commonly list 44-seat coaches, which are not presented here as 42-seaters.', 'A touring coach for larger groups. The exact vehicle and seating are confirmed with your quote.', '/assets/vehicles/coach-42-seater.jpg', '/assets/vehicles/coach-42-seater-480.jpg', 'White touring coach', 'ILLUSTRATIVE', 'Bob Adams from Amanzimtoti, South Africa', 'https://commons.wikimedia.org/wiki/File:Megacoach_Mercedes_Benz_coach_(15822372134).jpg', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', null, null, '2026-10-04', 6, true);
